var a=[{slug:"gastroenterologia",nazwa:"Gastroenterologia",opis:["Zapewniamy kompleksow\u0105 opiek\u0119 gastroenterologiczn\u0105 dla dzieci i doros\u0142ych, obejmuj\u0105c\u0105 konsultacje specjalistyczne, nowoczesn\u0105 diagnostyk\u0119 endoskopow\u0105 oraz leczenie chor\xF3b przewodu pokarmowego. Naszym celem jest szybkie i trafne rozpoznanie dolegliwo\u015Bci oraz wdro\u017Cenie skutecznej, indywidualnie dobranej terapii.","Specjalizujemy si\u0119 w diagnostyce schorze\u0144 prze\u0142yku, \u017Co\u0142\u0105dka, jelita cienkiego i grubego, takich jak m.in. refluks, choroba wrzodowa, zesp\xF3\u0142 jelita dra\u017Cliwego (IBS), nieswoiste choroby zapalne jelit (np. choroba Crohna, wrzodziej\u0105ce zapalenie jelita grubego), a tak\u017Ce w profilaktyce i wczesnym wykrywaniu zmian nowotworowych.","Prowadzimy konsultacje gastroenterologiczne dla doros\u0142ych i dla dzieci. Podczas wizyty lekarz przeprowadza szczeg\xF3\u0142owy wywiad, analizuje wyniki bada\u0144 oraz planuje dalsz\u0105 diagnostyk\u0119 lub leczenie.","Dbamy o komfort, bezpiecze\u0144stwo i dyskrecj\u0119 na ka\u017Cdym etapie diagnostyki i leczenia."],listy:[{tytul:"W naszej pracowni endoskopii wykonujemy",punkty:["gastroskopi\u0119 (badanie g\xF3rnego odcinka przewodu pokarmowego)","kolonoskopi\u0119 (badanie jelita grubego)"]},{tytul:"Formy znieczulenia",punkty:["znieczulenie miejscowe (z u\u017Cyciem lidokainy)","analgosedacja (sedacja do\u017Cylna zapewniaj\u0105ca komfort i ograniczenie odczu\u0107 b\xF3lowych)","znieczulenie anestezjologiczne w obecno\u015Bci lekarza anestezjologa"]},{tytul:"Zabiegi diagnostyczne i terapeutyczne",punkty:["usuwanie polip\xF3w (polipektomia)","pobieranie wycink\xF3w do bada\u0144 histopatologicznych","tamowanie drobnych krwawie\u0144 z przewodu pokarmowego","ocena zmian zapalnych i nowotworowych"]},{tytul:"Dlaczego warto nas wybra\u0107",punkty:["nowoczesny sprz\u0119t endoskopowy","r\xF3\u017Cne opcje znieczulenia dopasowane do potrzeb pacjenta","mo\u017Cliwo\u015B\u0107 wykonania diagnostyki i zabiegu podczas jednej wizyty","opieka do\u015Bwiadczonego zespo\u0142u specjalist\xF3w","przyjazne podej\u015Bcie do dzieci i doros\u0142ych"]}],cenniki:[{naglowek:"Konsultacje",weekend:!1,pozycje:[{usluga:"Konsultacja Gastroenterologiczna",cena:"od 300 do 350 z\u0142"},{usluga:"Konsultacja Gastroenterologiczna w weekend",cena:"od 400 do 450 z\u0142"}]},{naglowek:"Gastroskopia",weekend:!0,pozycje:[{usluga:"Gastroskopia",cena:"550z\u0142",cenaWeekend:"600z\u0142"},{usluga:"Gastroskopia z analgosedacj\u0105",cena:"900z\u0142",cenaWeekend:"1100z\u0142"},{usluga:"Gastroskopia w znieczuleniu og\xF3lnym",cena:"1300z\u0142"},{usluga:"Kolonoskopia + Gastroskopia w znieczuleniu og\xF3lnym",cena:"2500z\u0142"},{usluga:"Gastroskopia z testem na Helicobacter pylori",cena:"550z\u0142",cenaWeekend:"n/d"},{usluga:"Gastroskopia z testem na Helicobacter pylori + znieczulenie",cena:"900z\u0142",cenaWeekend:"n/d"}]},{naglowek:"Kolonoskopia",weekend:!0,pozycje:[{usluga:"Kolonoskopia",cena:"650z\u0142",cenaWeekend:"700z\u0142"},{usluga:"Kolonoskopia + znieczulenie (analgosedacja)",cena:"1000z\u0142",cenaWeekend:"1200z\u0142"},{usluga:"Kolonoskopia + Gastroskopia",cena:"1300z\u0142"},{usluga:"Kolonoskopia + Gastroskopia + znieczulenie (analgosedacja)",cena:"1600z\u0142",cenaWeekend:"2000z\u0142"},{usluga:"Kolonoskopia w znieczuleniu og\xF3lnym",cena:"1400z\u0142"},{usluga:"Kolonoskopia + Gastroskopia w znieczuleniu og\xF3lnym",cena:"2500z\u0142"},{usluga:"Sigmoidoskopia",cena:"500z\u0142",cenaWeekend:"n/d"},{usluga:"Usuni\u0119cie polip\xF3w",cena:"200z\u0142",cenaWeekend:"n/d"},{usluga:"Usuwanie polip\xF3w p\u0119tl\u0105",cena:"500z\u0142"},{usluga:"Wycinek do bada\u0144 histopatologicznych",cena:"130z\u0142",cenaWeekend:"n/d"}]}],lekarze:["dr n. med. Hubert Zatorski","lek. Micha\u0142 Stasiak","lek. Magdalena Bara\u0144ska","dr n. med. Milena Padysz","dr n. med. Dariusz Krzyczmanik","lek. Julia Banasik","dr n. med. i n. o zdr. Danuta Dom\u017Ca\u0142-Magrowska","Dr n. med. Izabela Kubi\u0144ska","Dr n.med. Krzysztof Grzegorczyk","Dr n. med. Rafa\u0142 Drozda"]},{slug:"chirurgia",nazwa:"Chirurgia",opis:["Oferujemy ambulatoryjn\u0105 opiek\u0119 chirurgiczn\u0105, obejmuj\u0105c\u0105 konsultacje oraz drobne zabiegi wykonywane w komfortowych i bezpiecznych warunkach.","Zapewniamy indywidualne podej\u015Bcie do pacjenta oraz dba\u0142o\u015B\u0107 o najwy\u017Csze standardy bezpiecze\u0144stwa i higieny."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje chirurgiczne","usuwanie szw\xF3w","zmian\u0119 opatrunk\xF3w","usuwanie znamion sk\xF3rnych","kwalifikacj\u0119 do dalszego leczenia chirurgicznego","kontrol\u0119 po zabiegach"]}],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacja chirurgiczna",cena:"350z\u0142"},{usluga:"Usuni\u0119cie szw\xF3w wraz z konsultacj\u0105",cena:"od 450z\u0142"},{usluga:"Wizyta kontrolna",cena:"200z\u0142"},{usluga:"Naci\u0119cie zakrzepu brze\u017Cnego",cena:"od 700z\u0142"},{usluga:"Zmiana opatrunku",cena:"od 250z\u0142"},{usluga:"Usuwanie znamion sk\xF3rnych",cena:"350-600z\u0142 (ka\u017Cdy kolejny 100z\u0142)"}]}],lekarze:["Dr n. med. Rafa\u0142 Drozda"]},{slug:"reumatologia",nazwa:"Reumatologia",opis:["Zajmujemy si\u0119 diagnostyk\u0105 oraz leczeniem chor\xF3b uk\u0142adu ruchu i schorze\u0144 reumatycznych. Pomagamy pacjentom zmagaj\u0105cym si\u0119 z b\xF3lem staw\xF3w, stanami zapalnymi oraz chorobami autoimmunologicznymi.","Nowoczesna diagnostyka obrazowa pozwala na szybk\u0105 i precyzyjn\u0105 ocen\u0119 stanu zdrowia pacjenta."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje reumatologiczne","badania USG narz\u0105du ruchu (staw\xF3w, \u015Bci\u0119gien, tkanek mi\u0119kkich)","diagnostyk\u0119 zmian zapalnych i zwyrodnieniowych","monitorowanie przebiegu leczenia"]}],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacja reumatologiczna",cena:"300z\u0142"},{usluga:"USG barku",cena:"200z\u0142"},{usluga:"USG r\u0119ki",cena:"200z\u0142"},{usluga:"USG stawu kolanowego",cena:"200z\u0142"},{usluga:"USG stawu skokowego",cena:"200z\u0142"},{usluga:"USG stawu \u0142okciowego",cena:"200z\u0142"},{usluga:"USG staw\xF3w barkowych",cena:"300z\u0142"},{usluga:"USG staw\xF3w kolanowych",cena:"300z\u0142"},{usluga:"USG staw\xF3w skokowych",cena:"300z\u0142"}]}],lekarze:["Dr Joanna Kowalska-Majka"]},{slug:"kardiologia",nazwa:"Kardiologia",opis:["Oferujemy kompleksow\u0105 opiek\u0119 kardiologiczn\u0105, obejmuj\u0105c\u0105 profilaktyk\u0119, diagnostyk\u0119 oraz leczenie chor\xF3b serca i uk\u0142adu kr\u0105\u017Cenia.","Zapewniamy profesjonaln\u0105 opiek\u0119 oraz nowoczesny sprz\u0119t diagnostyczny, co pozwala na szybkie i trafne rozpoznanie problem\xF3w kardiologicznych."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje kardiologiczne","badania EKG (elektrokardiografia)","badania ECHO serca (echokardiografia)","ocen\u0119 ryzyka sercowo-naczyniowego","diagnostyk\u0119 zaburze\u0144 rytmu serca i nadci\u015Bnienia"]}],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacja kardiologiczna",cena:"250z\u0142"},{usluga:"Konsultacja kardiologiczna + ECHO",cena:"350z\u0142"},{usluga:"USG serca (echo serca)",cena:"220z\u0142"},{usluga:"EKG spoczynkowe",cena:"40z\u0142"},{usluga:"EKG spoczynkowe z opisem kardiologa",cena:"90z\u0142"}]}],lekarze:["lek. \u0141ukasz Spadli\u0144ski","Dr n.med. Adam Rafa\u0142 Poliwczak"]},{slug:"psychologia",nazwa:"Psychologia",opis:["Twoje emocje maj\u0105 znaczenie - skorzystaj z profesjonalnego wsparcia psychologicznego! Szukasz pomocy, zrozumienia i konkretnych rozwi\u0105za\u0144? W naszym centrum medycznym oferujemy kompleksowe wsparcie dla dzieci, m\u0142odzie\u017Cy i doros\u0142ych. Pracujemy z empati\u0105, do\u015Bwiadczeniem i indywidualnym podej\u015Bciem do ka\u017Cdego pacjenta.","Nasz zesp\xF3\u0142 tworz\u0105 wykwalifikowani psycholodzy, terapeuci i mediatorzy, kt\xF3rzy \u0142\u0105cz\u0105 wieloletnie do\u015Bwiadczenie z empatycznym podej\u015Bciem do ka\u017Cdego pacjenta. Pracujemy z osobami w r\xF3\u017Cnym wieku i w r\xF3\u017Cnych sytuacjach \u017Cyciowych, zapewniaj\u0105c fachow\u0105 pomoc opart\u0105 na rzetelnej wiedzy i szacunku.","Wierzymy, \u017Ce skuteczna pomoc psychologiczna wymaga uwa\u017Cno\u015Bci na indywidualn\u0105 histori\u0119 i potrzeby ka\u017Cdego cz\u0142owieka. Dlatego nasza praca opiera si\u0119 na dok\u0142adnym zrozumieniu sytuacji pacjenta i dopasowaniu formy terapii do jego mo\u017Cliwo\u015Bci, cel\xF3w i tempa.","Tworzymy atmosfer\u0119 pe\u0142n\u0105 zrozumienia, \u017Cyczliwo\u015Bci i zaufania. Nasze gabinety to przestrze\u0144, w kt\xF3rej mo\u017Cesz m\xF3wi\u0107 swobodnie, bez oceniania i obaw.","Zr\xF3b pierwszy krok. Skontaktuj si\u0119 z nami i przekonaj si\u0119, \u017Ce pomoc jest bli\u017Cej, ni\u017C my\u015Blisz. Ciep\u0142o Ci\u0119 przywitamy i wsp\xF3lnie znajdziemy najlepsz\u0105 drog\u0119 do poprawy Twojego samopoczucia."],listy:[{tytul:"Oferta",punkty:["Kompleksowa oferta psychologiczna - diagnoza psychologiczna, terapia i specjalistyczne wsparcie dostosowane do indywidualnych potrzeb","Diagnoza psychologiczna - korzystamy z nowoczesnych metod, takich jak test inteligencji Stanford-Binet","TUS - Trening Umiej\u0119tno\u015Bci Spo\u0142ecznych, skuteczna metoda wspieraj\u0105ca dzieci i m\u0142odzie\u017C w budowaniu relacji, asertywno\u015Bci i kontroli emocji"]}],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacje (50 minut) - pierwsza wizyta",cena:"220 z\u0142"},{usluga:"Konsultacje (50 minut) - kolejna wizyta",cena:"200 z\u0142"},{usluga:"Terapia psychologiczna (50 minut) - pierwsza wizyta",cena:"220 z\u0142"},{usluga:"Terapia psychologiczna (50 minut) - kolejna wizyta",cena:"200 z\u0142"},{usluga:"Mediacje (60 minut) - pierwsza wizyta",cena:"450 z\u0142"},{usluga:"Mediacje (60 minut) - kolejna wizyta",cena:"400 z\u0142"},{usluga:"Za\u015Bwiadczenie psychologa",cena:"160 z\u0142"},{usluga:"Opinia psychologiczna",cena:"160 z\u0142"},{usluga:"Konsultacja diagnostyczna",cena:"280 z\u0142"},{usluga:"Skala Inteligencji Stanford-Binet 5 (SB5)",cena:"300 z\u0142"},{usluga:"Diagnoza spektrum autyzmu (5 wizyt) bez ADOS + wizyta u lekarza zgodnie z cennikiem",cena:"od 2100 z\u0142"},{usluga:"Diagnoza spektrum autyzmu (5 wizyt) z ADOS + wizyta u lekarza zgodnie z cennikiem",cena:"od 3000 z\u0142"},{usluga:"Test ADOS - raport z badania, wywiad 50 minut + test (2x50 minut)",cena:"od 1200 z\u0142"},{usluga:"MMPI-2 - pierwsza wizyta wywiad, druga i trzecia wizyta test",cena:"1100-1400 z\u0142"}]}],lekarze:["Dominika Buczy\u0144ska"]},{slug:"dietetyka",nazwa:"Dietetyka",opis:["Oferujemy profesjonalne wsparcie dietetyczne, oparte na indywidualnym podej\u015Bciu do potrzeb pacjenta. Pomagamy w poprawie nawyk\xF3w \u017Cywieniowych, redukcji masy cia\u0142a, budowaniu zdrowej sylwetki oraz wspieraniu leczenia diet\u0105 w r\xF3\u017Cnych jednostkach chorobowych.","Ka\u017Cdy plan \u017Cywieniowy opracowywany jest w oparciu o szczeg\xF3\u0142owy wywiad, uwzgl\u0119dniaj\u0105cy tryb \u017Cycia, aktywno\u015B\u0107 fizyczn\u0105, wyniki bada\u0144 oraz ewentualne choroby wsp\xF3\u0142istniej\u0105ce.","Pomagamy osi\u0105gn\u0105\u0107 trwa\u0142e efekty w zdrowy i bezpieczny spos\xF3b."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje dietetyczne","wizyty kontrolne monitoruj\u0105ce post\u0119py","analiz\u0119 sk\u0142adu cia\u0142a (m.in. poziom tkanki t\u0142uszczowej, masy mi\u0119\u015Bniowej i nawodnienia)","indywidualne jad\u0142ospisy dostosowane do stylu \u017Cycia, preferencji oraz stanu zdrowia","plany \u017Cywieniowe na 7, 14, 21 oraz 30 dni"]},{tytul:"Dlaczego warto skorzysta\u0107 z naszej opieki dietetycznej",punkty:["indywidualne podej\u015Bcie do ka\u017Cdego pacjenta","realne i mo\u017Cliwe do utrzymania zalecenia","wsparcie na ka\u017Cdym etapie zmiany nawyk\xF3w","jad\u0142ospisy dopasowane do codziennego trybu \u017Cycia","kompleksowe podej\u015Bcie do zdrowia i samopoczucia"]}],cenniki:[],lekarze:["mgr Paulina Kruk","Oliwia \u015Acigalska"]},{slug:"proktologia",nazwa:"Proktologia",opis:["Proktologia to dziedzina medycyny zajmuj\u0105ca si\u0119 diagnostyk\u0105, leczeniem oraz profilaktyk\u0105 chor\xF3b ko\u0144cowego odcinka przewodu pokarmowego - odbytnicy, kana\u0142u odbytu i okolic odbytu. Cho\u0107 schorzenia proktologiczne cz\u0119sto nale\u017C\u0105 do temat\xF3w kr\u0119puj\u0105cych dla pacjent\xF3w, ich wczesne rozpoznanie i odpowiednie leczenie pozwalaj\u0105 skutecznie wyeliminowa\u0107 dolegliwo\u015Bci oraz zapobiec powa\u017Cniejszym powik\u0142aniom.","W AmiCare zapewniamy kompleksow\u0105 opiek\u0119 proktologiczn\u0105 obejmuj\u0105c\u0105 konsultacje specjalistyczne, diagnostyk\u0119 oraz dob\xF3r indywidualnego leczenia. Zajmujemy si\u0119 rozpoznawaniem i leczeniem najcz\u0119stszych schorze\u0144 proktologicznych, takich jak hemoroidy, szczeliny odbytu, przetoki, ropnie oko\u0142oodbytnicze, polipy oraz innych chor\xF3b ko\u0144cowego odcinka jelita grubego.","Do objaw\xF3w, kt\xF3re powinny sk\u0142oni\u0107 do konsultacji z proktologiem, nale\u017C\u0105 mi\u0119dzy innymi: b\xF3l podczas wypr\xF3\u017Cniania, krwawienie z odbytu, \u015Bwi\u0105d, pieczenie, uczucie dyskomfortu lub niepe\u0142nego wypr\xF3\u017Cnienia, a tak\u017Ce przewlek\u0142e zaparcia lub biegunki. Wiele schorze\u0144 proktologicznych rozwija si\u0119 stopniowo, dlatego nie warto odk\u0142ada\u0107 wizyty u specjalisty.","Pacjentami poradni proktologicznej AmiCare opiekuje si\u0119 dr n. med. Rafa\u0142 Drozda - specjalista chirurgii og\xF3lnej i onkologicznej, gastroenterolog oraz proktolog, od lat zajmuj\u0105cy si\u0119 diagnostyk\u0105 i leczeniem chor\xF3b przewodu pokarmowego oraz schorze\u0144 proktologicznych.","Dbamy o komfort, dyskrecj\u0119 i bezpiecze\u0144stwo ka\u017Cdego pacjenta, zapewniaj\u0105c profesjonaln\u0105 opiek\u0119 medyczn\u0105 oraz indywidualne podej\u015Bcie na ka\u017Cdym etapie diagnostyki i leczenia."],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacja proktologiczna",cena:"350z\u0142"}]}],lekarze:["Dr n. med. Rafa\u0142 Drozda"]}];export{a};
